import {
  Component,
  OnInit,
  OnDestroy,
  Inject,
  PLATFORM_ID,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  ViewChild,
  ElementRef,
  effect,
} from '@angular/core';
import { CommonModule, DOCUMENT, isPlatformBrowser } from '@angular/common';
import { RouterModule } from '@angular/router';
import { environment } from '../../../environments/environment';
import { TranslationService } from '../../core/services/translation.service';
import { TranslateModule } from '@ngx-translate/core';

declare var lottie: any;

@Component({
  selector: 'app-website-popup',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, RouterModule, TranslateModule],
  templateUrl: './website-popup.component.html',
  styleUrls: ['./website-popup.component.scss'],
})
export class WebsitePopupComponent implements OnInit, OnDestroy {

  isVisible = false;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private lottieInstance: any = null;
  private containerEl: HTMLElement | null = null;
  baseUrl: string;

  // The container only exists while the popup is open (*ngIf), so init from the setter
  @ViewChild('lottieContainer') set lottieContainer(el: ElementRef<HTMLElement> | undefined) {
    this.containerEl = el?.nativeElement ?? null;
    if (this.containerEl && !this.lottieInstance) {
      this.initLottie(this.containerEl);
    }
  }

  constructor(
    @Inject(PLATFORM_ID) private platformId: Object,
    @Inject(DOCUMENT) private document: Document,
    private cdr: ChangeDetectorRef,
    public translationService: TranslationService
  ) {
    this.baseUrl = environment.url;

    // Reload the animation with the correct-language file when the user
    // switches language while the popup is already open.
    effect(() => {
      this.translationService.currentLang();
      if (this.containerEl && this.lottieInstance) {
        this.destroyLottie();
        this.initLottie(this.containerEl);
      }
    });
  }

  ngOnInit(): void {
    if (!isPlatformBrowser(this.platformId)) return;
    this.loadLottieScript();
    this.timer = setTimeout(() => {
      this.isVisible = true;
      this.cdr.markForCheck();
    }, 5000);
  }

  ngOnDestroy(): void {
    if (this.timer) clearTimeout(this.timer);
    this.destroyLottie();
  }

  close(): void {
    this.isVisible = false;
    this.destroyLottie();
    this.cdr.markForCheck();
  }

  private loadLottieScript(): void {
    if (this.document.getElementById('lottie-script')) return;
    const script = this.document.createElement('script');
    script.id = 'lottie-script';
    script.src = '/lottie/lottie.js';
    script.async = true;
    this.document.body.appendChild(script);
  }

  private initLottie(container: HTMLElement): void {
    if (!isPlatformBrowser(this.platformId)) return;
    if (typeof lottie === 'undefined') {
      // Script may still be loading; retry while the popup is open
      setTimeout(() => {
        if (this.isVisible && !this.lottieInstance) this.initLottie(container);
      }, 100);
      return;
    }
    this.lottieInstance = lottie.loadAnimation({
      container,
      renderer: 'svg',
      loop: true,
      autoplay: true,
      path: this.getLottiePath(),
    });
  }

  private getLottiePath(): string {
    return this.translationService.currentLang() === 'ar'
      ? '/lottie/search-arabic.json'
      : '/lottie/search.json';
  }

  private destroyLottie(): void {
    if (this.lottieInstance) {
      this.lottieInstance.destroy();
      this.lottieInstance = null;
    }
  }
}
